@page "/dashboard"
@rendermode InteractiveServer
@using sv_71220ce7f8dc4fd789b2e55996217fa1.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="alert alert-info">
    <strong>Current Warehouse:</strong> @WarehouseState.CurrentWarehouseName
</div>

<div class="card" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low Stock Alerts</h5>
        <p class="card-text">
            <span class="display-4 text-danger">@AlertService.LatestLowStockCount</span>
            <span class="text-muted ms-2">items below minimum level</span>
        </p>
        <small class="text-muted">Refreshes every 10 seconds</small>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        // Subscribe to alert polling — starts the timer if we're the first subscriber
        AlertService.Subscribe();

        // Listen for changes from either service so we re-render
        AlertService.OnAlertDataChanged += OnDataChanged;
        WarehouseState.OnChange += OnDataChanged;
    }

    private void OnDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnDataChanged;
        WarehouseState.OnChange -= OnDataChanged;
        AlertService.Unsubscribe();
    }
}

